def build_offers():
    out=[]
    for ident,label,base in [(NEW_IDS[0],'HWA PYP · оба ребёнка · одна полная неделя',1490),(NEW_IDS[1],'HWA PYP · оба ребёнка · две полные недели',2850)]:
        out.append(offer(ident,'hwa-winter-pyp',label,base,currency='SGD',price_year=2027,format='day',checked=CHECKED,
            sessions=HSESS[:4]+HSESS[5:] if base==1490 else [],sources=[HWA,HP,HR],
            unknown_required=[dict(id='package_difference',label='Разница итогового пакета: питание, форма, регистрация, страхование · включение и сумму согласовать',unit='amount',rate=1,min=0)],
            gate='Оба 6–12 по 2027 возрастам, но требуются G1–6, место и согласование двуязычной программы без Mandarin. Не англоязычный robotics интенсив.',
            included='Опубликованная таблица базовых тарифов; перечисление включений в PDF требует согласования с сайтом.',deposit_note=HREFUND,
            scope=f'{base} SGD за ребёнка, {base*2} за обоих по опубликованному тарифу; это частичная смета. '+HCONFLICT+' Короткая1–4Feb и спорная15Feb смены исключены из этой цены. Две недели выбрать как реально доступный согласованный комплект; широкий интервал не обещает занятия по выходным.'))
    return out

def extend_planning_v125(d):
    m=d['camp_planning'];out=build_offers();authored={q['id']:q for q in out};existing={q['id'] for q in m['offers']}
    m['offers']=[authored.get(q['id'],q) for q in m['offers']]+[q for q in out if q['id'] not in existing]
    m.update(version=125,asof=CHECKED)
